async function armPhysicalCheckpoint(spec){await page.evaluate(spec=>{clearInterval(window.__physicalCheckpointTimer);window.__physicalCheckpoint={spec,active:true,hit:null,error:null,lastTick:null,observations:0,maxSnapshotMs:0};window.__physicalCheckpointTimer=setInterval(()=>{const watch=window.__physicalCheckpoint;if(watch.hit||watch.error)return;try{const tick=window.courtyardQA.renderer.view.tick;if(tick===watch.lastTick)return;watch.lastTick=tick;const started=performance.now(),s=window.courtyardQA.snapshot().state;watch.observations++;watch.maxSnapshotMs=Math.max(watch.maxSnapshotMs,performance.now()-started);const p=s.personsById['person:master'],y=p.scenic?.bodyYield,o=s.workOrdersById[spec.orderId];let match=false;if(spec.kind==='retreat')match=y?.kind==='transport-retreat'&&y.requestedBy===spec.blockerId&&y.activityId===spec.activityId&&y.workOrderId===spec.orderId&&Math.hypot(p.scenic.x-spec.origin.x,p.scenic.y-spec.origin.y)>.04;else if(spec.kind==='delivery')match=o?.phase==='delivered';else{const process=o?.process;if(process?.stageIndex>spec.stageIndex)throw Error('alchemy stage passed its armed physical checkpoint');match=process?.stageIndex===spec.stageIndex&&process.stageProgressTicks>=2;}if(match){if(!window.courtyardQA.status().manualPause){const button=document.getElementById('pause');if(!button||button.disabled)throw Error('public pause button unavailable');button.click();}if(!window.courtyardQA.status().manualPause)throw Error('public pause did not hold physical checkpoint');watch.hit={tick:s.worldTick,observed:spec.kind==='retreat'?{bodyYield:JSON.parse(JSON.stringify(y))}:spec.kind==='delivery'?{phase:o.phase}:{stageIndex:o.process.stageIndex,stageProgressTicks:o.process.stageProgressTicks}};clearInterval(window.__physicalCheckpointTimer);}}catch(e){watch.error=String(e.stack||e);clearInterval(window.__physicalCheckpointTimer);}},20);},spec);}
async function awaitPhysicalCheckpoint(label,seconds=1200){const start=Date.now();while(Date.now()-start<seconds*1000){if(stopRequested){await page.evaluate(()=>clearInterval(window.__physicalCheckpointTimer));await checkStop();}await checkStop();const observation=await page.evaluate(()=>window.__physicalCheckpoint);assert(!observation.error,observation.error);if(observation.hit){await page.evaluate(()=>{window.__physicalCheckpoint.active=false;});record('公开按钮捕获实际身体短窗口',{label,...observation.hit,spec:observation.spec,observations:observation.observations,maxSnapshotMs:observation.maxSnapshotMs});return;}await sleep(250);}await page.evaluate(()=>clearInterval(window.__physicalCheckpointTimer));throw Error('Timed out waiting for '+label);}
