 await flushTrail();await checkStop();lastTick=r.view.tick;if(!observations.length||Math.floor(lastTick/1200)!==Math.floor(observations.at(-1).tick/1200))await collectSupply();if(inspectionHeld&&productionFoodEnabled)assert(quantity(r.session.state,HOME,'food')>=productionDaily*2,'production inspection retains the two-day actual food floor');if(!matched&&!inspectionHeld&&await productionFoodCheckpoint(r.session.state))continue;
 if(last!==lastTick){last=lastTick;const gs=geometrySampleState;for(const k of Object.keys(gs))delete gs[k];Object.assign(gs,r.session.state,{buildings:Object.values(r.session.state.buildingsById)});const invalid=r.view.people.filter(p=>{if(p.indoor)return false;const d=r.view.domain,western=d.westWorkshopsEnabled&&p.x<-38;let clear;if(western){const evidence=westernBodyEvidence(p,d,gs);clear=evidence.clear;if(!clear)(r.westernFailures??=[]).push(evidence);}else clear=feetClear(p,d,gs);return !clear;}).map(p=>p.id);if(invalid.length)await fs.writeFile(path.join(output,'first-invalid-body-sample.json'),JSON.stringify({sample:r,invalid,full:await read()},null,2)+'\n');assert.deepEqual(invalid,[],'body/doorway/road geometry');observations.push({phase,tick:lastTick,wallSeconds:wall(),master:r.session.state.personsById[MASTER].position,activity:r.view.operations.master.activity});}
