 for(const id of ['person:master',...original.state.homeMemberIds]){const before=original.state.personsById[id],after=paused.session.state.personsById[id];assert(after);assert.equal(after.personId,before.personId);assert.equal(after.name,before.name);assert.deepEqual(after.appearance,before.appearance);}
